private static ResponseEntity<Map<String, String>> text(HttpStatus status, String body) {
    return ResponseEntity.status(status).contentType(MediaType.APPLICATION_JSON).body(Map.of("detail", body));
}

private Mono<ServerResponse> serve(Path path) {
    Resource resource = new FileSystemResource(path);
    MediaType mediaType = MediaTypeFactory.getMediaType(resource)
            .orElse(MediaType.APPLICATION_OCTET_STREAM);
    ServerResponse.BodyBuilder builder = ServerResponse.ok().contentType(mediaType);
    try {
        builder.lastModified(java.time.Instant.ofEpochMilli(Files.getLastModifiedTime(path).toMillis()));
    } catch (java.io.IOException ignored) {
        // 读取修改时间失败时退化为不带校验头
    }
    builder.cacheControl(path.equals(indexFile)
            ? org.springframework.http.CacheControl.noCache()
            : org.springframework.http.CacheControl.maxAge(java.time.Duration.ofDays(365)).cachePublic().immutable());
    return builder.body(BodyInserters.fromResource(resource));
}

@property
def ak_module(self) -> Any:
    if self._ak_module is None:
        import akshare as ak

        from fund_advisor_data_core.audit import SUPPORTED_AKSHARE_VERSION
        from fund_advisor_data_core.errors import DataCoreError

        actual_version = getattr(ak, "__version__", None)
        if actual_version != SUPPORTED_AKSHARE_VERSION:
            raise DataCoreError(
                "AKSHARE_VERSION_MISMATCH",
                "AKShare 版本未经验证，拒绝继续以避免字段错位",
                {"expected": SUPPORTED_AKSHARE_VERSION, "actual": actual_version},
            )
        self._ak_module = ak
    return self._ak_module

@staticmethod
def _purchase_row(frame: pd.DataFrame, code: str) -> pd.Series | None:
    matched = frame[frame["基金代码"].map(normalize_code).eq(normalize_code(code))]
    if len(matched) > 1:
        raise DataCoreError(
            "AMBIGUOUS_PURCHASE_RECORD",
            f"申购状态表中基金 {code} 命中多行记录，无法确认唯一状态",
            {"code": code, "matched_rows": int(len(matched))},
        )
    return matched.iloc[0] if not matched.empty else None

RETRYABLE_CODES = frozenset(
    {
        "DATA_SOURCE_ERROR",
        "RATE_LIMITED",
        "UPSTREAM_TIMEOUT",
    }
)


class DataCoreError(Exception):
    def __init__(
        self,
        code: str,
        message: str,
        details: dict[str, Any] | None = None,
    ) -> None:
        super().__init__(message)
        self.code = code
        self.message = message
        self.details = details or {}

    @property
    def retryable(self) -> bool:
        return self.code in RETRYABLE_CODES

